#include "NavigationAsset.h"
bool BakeNavigation(const Scene& scene,const SceneObject& surface,const ProjectNavigation& project,NavigationData& out,std::string& error,const AssetDatabase* assets){NavigationGeometry geometry;if(!CollectNavigationGeometry(scene,surface,project,geometry,error,assets))return false;return BakeNavigationGeometry(geometry,*surface.navigationSurface,project.profiles.at(surface.navigationSurface->profile),out,error);}
